-- ============================================================
-- TABLE: users
-- Purpose: Auth accounts for admin and cashier staff.
-- Roles: 'admin' (full access) | 'cashier' (restricted)
-- username is auto-generated by the app (e.g. "staff_8f3a").
-- password stored as plain text (V1 — hash in V2).
-- ============================================================

CREATE TABLE IF NOT EXISTS users (
  id           TEXT PRIMARY KEY NOT NULL,

  full_name    TEXT NOT NULL,
  username     TEXT NOT NULL,
  password     TEXT NOT NULL,

  role         TEXT NOT NULL DEFAULT 'admin'
               CHECK (role IN ('admin', 'cashier')),

  phone        TEXT,
  email        TEXT,

  is_active    INTEGER NOT NULL DEFAULT 1
               CHECK (is_active IN (0, 1)),

  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

CREATE UNIQUE INDEX IF NOT EXISTS users_username_uq ON users (username);
